1	import { z } from "zod";
2	import {
3	  AUTH_BASE_URL_MODES,
4	  BIND_MODES,
5	  DEPLOYMENT_EXPOSURES,
6	  DEPLOYMENT_MODES,
7	  SECRET_PROVIDERS,
8	  STORAGE_PROVIDERS,
9	} from "./constants.js";
10	import { validateConfiguredBindMode } from "./network-bind.js";
11	
12	export const configMetaSchema = z.object({
13	  version: z.literal(1),
14	  updatedAt: z.string(),
15	  source: z.enum(["onboard", "configure", "doctor"]),
16	});
17	
18	export const llmConfigSchema = z.object({
19	  provider: z.enum(["claude", "openai"]),
20	  apiKey: z.string().optional(),
21	});
22	
23	export const databaseBackupConfigSchema = z.object({
24	  enabled: z.boolean().default(true),
25	  intervalMinutes: z.number().int().min(1).max(7 * 24 * 60).default(60),
26	  retentionDays: z.number().int().min(1).max(3650).default(7),
27	  dir: z.string().default("~/.paperclip/instances/default/data/backups"),
28	});
29	
30	export const databaseConfigSchema = z.object({
31	  mode: z.enum(["embedded-postgres", "postgres"]).default("embedded-postgres"),
32	  connectionString: z.string().optional(),
33	  embeddedPostgresDataDir: z.string().default("~/.paperclip/instances/default/db"),
34	  embeddedPostgresPort: z.number().int().min(1).max(65535).default(54329),
35	  backup: databaseBackupConfigSchema.default({
36	    enabled: true,
37	    intervalMinutes: 60,
38	    retentionDays: 7,
39	    dir: "~/.paperclip/instances/default/data/backups",
40	  }),
41	});
42	
43	export const loggingConfigSchema = z.object({
44	  mode: z.enum(["file", "cloud"]),
45	  logDir: z.string().default("~/.paperclip/instances/default/logs"),
46	});
47	
48	export const serverConfigSchema = z.object({
49	  deploymentMode: z.enum(DEPLOYMENT_MODES).default("local_trusted"),
50	  exposure: z.enum(DEPLOYMENT_EXPOSURES).default("private"),
51	  bind: z.enum(BIND_MODES).optional(),
52	  customBindHost: z.string().optional(),
53	  host: z.string().default("127.0.0.1"),
54	  port: z.number().int().min(1).max(65535).default(3100),
55	  allowedHostnames: z.array(z.string().min(1)).default([]),
56	  serveUi: z.boolean().default(true),
57	});
58	
59	export const authConfigSchema = z.object({
60	  baseUrlMode: z.enum(AUTH_BASE_URL_MODES).default("auto"),
61	  publicBaseUrl: z.string().url().optional(),
62	  disableSignUp: z.boolean().default(false),
63	});
64	
65	export const storageLocalDiskConfigSchema = z.object({
66	  baseDir: z.string().default("~/.paperclip/instances/default/data/storage"),
67	});
68	
69	export const storageS3ConfigSchema = z.object({
70	  bucket: z.string().min(1).default("paperclip"),
71	  region: z.string().min(1).default("us-east-1"),
72	  endpoint: z.string().optional(),
73	  prefix: z.string().default(""),
74	  forcePathStyle: z.boolean().default(false),
75	});
76	
77	export const storageR2ConfigSchema = z.object({
78	  bucket: z.string().min(1).default("paperclip"),
79	  prefix: z.string().default(""),
80	  accountId: z.string().optional(),
81	});
82	
83	export const storageConfigSchema = z.object({
84	  provider: z.enum(STORAGE_PROVIDERS).default("local_disk"),
85	  localDisk: storageLocalDiskConfigSchema.default({
86	    baseDir: "~/.paperclip/instances/default/data/storage",
87	  }),
88	  s3: storageS3ConfigSchema.default({
89	    bucket: "paperclip",
90	    region: "us-east-1",
91	    prefix: "",
92	    forcePathStyle: false,
93	  }),
94	  r2: storageR2ConfigSchema.default({
95	    bucket: "paperclip",
96	    prefix: "",
97	  }),
98	});
99	
100	export const secretsLocalEncryptedConfigSchema = z.object({
101	  keyFilePath: z.string().default("~/.paperclip/instances/default/secrets/master.key"),
102	});
103	
104	export const secretsConfigSchema = z.object({
105	  provider: z.enum(SECRET_PROVIDERS).default("local_encrypted"),
106	  strictMode: z.boolean().default(false),
107	  localEncrypted: secretsLocalEncryptedConfigSchema.default({
108	    keyFilePath: "~/.paperclip/instances/default/secrets/master.key",
109	  }),
110	});
111	
112	export const telemetryConfigSchema = z.object({
113	  enabled: z.boolean().default(true),
114	}).default({});
115	
116	export const paperclipConfigSchema = z
117	  .object({
118	    $meta: configMetaSchema,
119	    llm: llmConfigSchema.optional(),
120	    database: databaseConfigSchema,
121	    logging: loggingConfigSchema,
122	    server: serverConfigSchema,
123	    telemetry: telemetryConfigSchema,
124	    auth: authConfigSchema.default({
125	      baseUrlMode: "auto",
126	      disableSignUp: false,
127	    }),
128	    storage: storageConfigSchema.default({
129	      provider: "local_disk",
130	      localDisk: {
131	        baseDir: "~/.paperclip/instances/default/data/storage",
132	      },
133	      s3: {
134	        bucket: "paperclip",
135	        region: "us-east-1",
136	        prefix: "",
137	        forcePathStyle: false,
138	      },
139	    }),
140	    secrets: secretsConfigSchema.default({
141	      provider: "local_encrypted",
142	      strictMode: false,
143	      localEncrypted: {
144	        keyFilePath: "~/.paperclip/instances/default/secrets/master.key",
145	      },
146	    }),
147	  })
148	  .superRefine((value, ctx) => {
149	    if (value.server.deploymentMode === "local_trusted" && value.server.exposure !== "private") {
150	      ctx.addIssue({
151	        code: z.ZodIssueCode.custom,
152	        message: "server.exposure must be private when deploymentMode is local_trusted",
153	        path: ["server", "exposure"],
154	      });
155	    }
156	
157	    for (const message of validateConfiguredBindMode({
158	      deploymentMode: value.server.deploymentMode,
159	      deploymentExposure: value.server.exposure,
160	      bind: value.server.bind,
161	      host: value.server.host,
162	      customBindHost: value.server.customBindHost,
163	    })) {
164	      ctx.addIssue({
165	        code: z.ZodIssueCode.custom,
166	        message,
167	        path: message.includes("customBindHost") ? ["server", "customBindHost"] : ["server", "bind"],
168	      });
169	    }
170	
171	    if (value.auth.baseUrlMode === "explicit" && !value.auth.publicBaseUrl) {
172	      ctx.addIssue({
173	        code: z.ZodIssueCode.custom,
174	        message: "auth.publicBaseUrl is required when auth.baseUrlMode is explicit",
175	        path: ["auth", "publicBaseUrl"],
176	      });
177	    }
178	
179	    if (value.server.exposure === "public" && value.auth.baseUrlMode !== "explicit") {
180	      ctx.addIssue({
181	        code: z.ZodIssueCode.custom,
182	        message: "auth.baseUrlMode must be explicit when deploymentMode=authenticated and exposure=public",
183	        path: ["auth", "baseUrlMode"],
184	      });
185	    }
186	
187	    if (value.server.exposure === "public" && !value.auth.publicBaseUrl) {
188	      ctx.addIssue({
189	        code: z.ZodIssueCode.custom,
190	        message: "auth.publicBaseUrl is required when deploymentMode=authenticated and exposure=public",
191	        path: ["auth", "publicBaseUrl"],
192	      });
193	    }
194	  });
195	
196	export type PaperclipConfig = z.infer<typeof paperclipConfigSchema>;
197	export type LlmConfig = z.infer<typeof llmConfigSchema>;
198	export type DatabaseConfig = z.infer<typeof databaseConfigSchema>;
199	export type LoggingConfig = z.infer<typeof loggingConfigSchema>;
200	export type ServerConfig = z.infer<typeof serverConfigSchema>;
201	export type StorageConfig = z.infer<typeof storageConfigSchema>;
202	export type StorageLocalDiskConfig = z.infer<typeof storageLocalDiskConfigSchema>;
203	export type StorageS3Config = z.infer<typeof storageS3ConfigSchema>;
204	export type StorageR2Config = z.infer<typeof storageR2ConfigSchema>;
205	export type SecretsConfig = z.infer<typeof secretsConfigSchema>;
206	export type SecretsLocalEncryptedConfig = z.infer<typeof secretsLocalEncryptedConfigSchema>;
207	export type AuthConfig = z.infer<typeof authConfigSchema>;
208	export type TelemetryConfig = z.infer<typeof telemetryConfigSchema>;
209	export type ConfigMeta = z.infer<typeof configMetaSchema>;
210	export type DatabaseBackupConfig = z.infer<typeof databaseBackupConfigSchema>;
211
